<?php
declare(strict_types=1);
$file = __DIR__ . '/data/ai_models_weekly.json';
$payload = is_file($file) ? json_decode((string) file_get_contents($file), true) : null;
function model_h(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$models = is_array($payload) ? (array)($payload['models'] ?? []) : [];
?>
