<?php if ($models): ?><section class="grid">
<?php foreach ($models as $i => $model): ?><article class="card"><div class="top"><span class="rank">#<?= $i + 1 ?> · <?= model_h((string)$model['category']) ?></span><span class="badge"><?= model_h((string)$model['region']) ?></span></div><h2><a href="<?= model_h((string)$model['url']) ?>" target="_blank" rel="noopener"><?= model_h((string)$model['name']) ?></a></h2><div class="vendor"><?= model_h((string)$model['company']) ?> · <?= model_h((string)$model['source']) ?> · <?= model_h((string)$model['release_date']) ?></div><div class="desc"><?= model_h((string)($model['description'] ?? '')) ?></div><div class="meta"><?php if (isset($model['downloads'])): ?><span>下载 <?= number_format((int)$model['downloads']) ?></span><?php endif; ?><?php if (isset($model['likes'])): ?><span>♥ <?= number_format((int)$model['likes']) ?></span><?php endif; ?><?php if (isset($model['stars'])): ?><span>★ <?= number_format((int)$model['stars']) ?></span><?php endif; ?><?php if (!empty($model['tags'])): ?><span><?= model_h(implode(' · ', array_slice((array)$model['tags'], 0, 3))) ?></span><?php endif; ?></div></article><?php endforeach; ?></section>
<?php else: ?><div class="notice empty">本周暂无已收录的新模型。榜单每周由后台脚本更新；请查看 README 的“每周 AI 模型榜”运行说明。</div><?php endif; ?>
